  [data-slot="sidebar-panel"][data-collapsible="icon"]
    [data-slot="sidebar-menu-button"] {
    width: 32px;
    height: 32px;
    padding: 0;
    justify-content: center;
    gap: 0;
  }

  [data-slot="sidebar-panel"][data-collapsible="icon"]
    [data-slot="sidebar-menu-button"]
    > :not(svg):not([data-sidebar-icon]) {
    display: none;
  }

  /* ---------------------------------------------------------------- */
  /* MenuAction & MenuBadge                                           */
  /* ---------------------------------------------------------------- */

  [data-slot="sidebar-menu-action"] {
    position: absolute;
    inset-block-start: 4px;
    inset-inline-end: 4px;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    padding: 0;
    border: 0;
    border-radius: 4px;
    background: transparent;
    color: var(--v2-icon-icon-muted);
    cursor: pointer;
    outline: none;
    transition:
      opacity 100ms ease-out,
      background-color 85ms ease-out,
      color 85ms ease-out;
  }

  [data-slot="sidebar-menu-item"]:has([data-slot="sidebar-menu-button"][data-size="sm"])
    [data-slot="sidebar-menu-action"] {
    inset-block-start: 2px;
  }

  [data-slot="sidebar-menu-item"]:has([data-slot="sidebar-menu-button"][data-size="lg"])
    [data-slot="sidebar-menu-action"] {
    inset-block-start: 10px;
  }

  [data-slot="sidebar-menu-action"] svg {
    width: 14px;
    height: 14px;
    flex-shrink: 0;
  }

  @media (hover: hover) {
    [data-slot="sidebar-menu-action"]:hover {
      background: var(--v2-overlay-simple-overlay-hover);
      color: var(--v2-icon-icon-base);
    }

    [data-slot="sidebar-menu-action"][data-show-on-hover] {
      opacity: 0;
    }

    [data-slot="sidebar-menu-item"]:is(:hover, :focus-within)
      [data-slot="sidebar-menu-action"][data-show-on-hover],
    [data-slot="sidebar-menu-action"][data-show-on-hover][data-open],
    [data-slot="sidebar-menu-action"][data-show-on-hover][aria-expanded="true"] {
      opacity: 1;
    }
  }

  [data-slot="sidebar-menu-action"]:focus-visible {
    opacity: 1;
    outline: 2px solid var(--v2-border-border-focus);
    outline-offset: 1px;
  }

  [data-slot="sidebar-panel"][data-collapsible="icon"]
    [data-slot="sidebar-menu-action"] {
    display: none;
  }

  [data-slot="sidebar-menu-badge"] {
    position: absolute;
    inset-block-start: 50%;
    inset-inline-end: 6px;
    transform: translateY(-50%);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 18px;
    height: 18px;
    padding: 0 5px;
    border-radius: 4px;
    font-size: 11px;
    font-weight: 530;
    line-height: 1;
    font-variant-numeric: tabular-nums;
    color: var(--v2-text-text-faint);
    pointer-events: none;
    user-select: none;
  }

  [data-slot="sidebar-menu-item"]:has([data-slot="sidebar-menu-button"]:is([data-sidebar-active], [aria-current="page"]))
    [data-slot="sidebar-menu-badge"] {
    color: var(--v2-text-text-base);
  }

  [data-slot="sidebar-panel"][data-collapsible="icon"]
    [data-slot="sidebar-menu-badge"] {
    display: none;
  }

  /* ---------------------------------------------------------------- */
  /* MenuSkeleton                                                     */
  /* ---------------------------------------------------------------- */

  [data-slot="sidebar-menu-skeleton"] {
    display: flex;
    align-items: center;
    gap: 8px;
    height: 28px;
    padding: 0 8px;
    border-radius: 6px;
  }

  /* The bars are Skeletons (skeleton.css: the console's fill, shimmer, fade-in
     and reduced motion); the sidebar only sizes them. */
  [data-slot="sidebar-menu-skeleton"] > [data-sidebar-skeleton="icon"] {
    width: 16px;
    height: 16px;
    flex-shrink: 0;
  }

  [data-slot="sidebar-menu-skeleton"] > [data-sidebar-skeleton="text"] {
    height: 12px;
    flex: 1;
    max-width: var(--skeleton-width, 72%);
  }

  /* ---------------------------------------------------------------- */
  /* MenuSub, MenuSubItem, MenuSubButton                              */
  /* ---------------------------------------------------------------- */

  [data-slot="sidebar-menu-sub"] {
    display: flex;
    flex-direction: column;
    min-width: 0;
    margin: 2px 0 2px 14px;
    padding: 2px 0 2px 10px;
    gap: 2px;
    list-style: none;
    border-inline-start: 1px solid var(--v2-border-border-muted);
  }

  [data-slot="sidebar-panel"][data-collapsible="icon"]
    [data-slot="sidebar-menu-sub"] {
    display: none;
  }

  [data-slot="sidebar-menu-sub-item"] {
    position: relative;
    min-width: 0;
  }

  [data-slot="sidebar-menu-sub-button"] {
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    min-width: 0;
    height: 26px;
    padding: 0 8px;
    border: 0;
    border-radius: 5px;
    background: transparent;
    color: var(--v2-text-text-muted);
    font-family: inherit;
    font-size: 12.5px;
    font-weight: 440;
    line-height: 18px;
    letter-spacing: -0.04px;
    text-align: start;
    text-decoration: none;
    user-select: none;
    cursor: pointer;
    outline: none;
    overflow: hidden;
    transition:
      background-color 85ms ease-out,
      color 85ms ease-out;
  }

  [data-slot="sidebar-menu-sub-button"][data-size="sm"] {
    height: 24px;
    font-size: 12px;
  }

  [data-slot="sidebar-menu-sub-button"] > span:last-child {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  [data-slot="sidebar-menu-sub-button"] svg {
    width: 14px;
    height: 14px;
    flex-shrink: 0;
    color: var(--v2-icon-icon-muted);
  }

  @media (hover: hover) {
    [data-slot="sidebar-menu-sub-button"]:hover:not(
        [data-sidebar-active],
        [aria-current="page"],
        :disabled,
        [data-disabled]
      ) {
      background: var(--v2-overlay-simple-overlay-hover);
      color: var(--v2-text-text-base);
    }
  }

  [data-slot="sidebar-menu-sub-button"]:is([data-sidebar-active], [aria-current="page"]) {
    background: var(--v2-background-bg-layer-03);
    color: var(--v2-text-text-base);
    font-weight: 530;
  }

  [data-slot="sidebar-menu-sub-button"]:focus-visible {
    outline: 2px solid var(--v2-border-border-focus);
    outline-offset: -1px;
  }

  [data-slot="sidebar-menu-sub-button"]:is(:disabled, [data-disabled], [aria-disabled="true"]) {
    opacity: 0.5;
    cursor: not-allowed;
    pointer-events: none;
  }

  /* ---------------------------------------------------------------- */
  /* Reduced motion                                                   */
  /* ---------------------------------------------------------------- */

  @media (prefers-reduced-motion: reduce) {
    [data-slot="sidebar-panel"],
    [data-slot="sidebar-trigger"],
    [data-slot="sidebar-rail"]::after,
    [data-slot="sidebar-group-label"],
    [data-slot="sidebar-group-action"],
    [data-slot="sidebar-menu-button"],
    [data-slot="sidebar-menu-action"],
    [data-slot="sidebar-menu-sub-button"] {
      transition: none;
    }
  }
}
